// The total of a receipt in yen: the sum of the lines, less the discount (a whole percent), rounded down to the yen.
export function receiptTotal(lines, discountPercent = 0) {
  if (!Number.isInteger(discountPercent) || discountPercent < 0 || discountPercent > 100) {
    throw new RangeError(`discountPercent must be an integer from 0 to 100, got ${discountPercent}`);
  }
  const subtotal = lines.reduce((sum, line) => sum + line.price * line.qty, 0);
  // in integers: subtotal * (1 - p / 100) is not exact in floating point (300 yen at 30 % came out as 209)
  return Math.floor((subtotal * (100 - discountPercent)) / 100);
}

